function makeDecor(){const mat=new THREE.MeshStandardMaterial({color:0x5c9b65,roughness:.35,metalness:.08});const goldMat=new THREE.MeshStandardMaterial({color:0xd8bc6f,metalness:.8,roughness:.24});for(let i=0;i<22;i++){const angle=i/22*Math.PI*2,r=14+Math.random()*5,x=Math.cos(angle)*r,z=Math.sin(angle)*r;const stem=new THREE.Mesh(new THREE.CylinderGeometry(.035,.06,.65+Math.random()*.45,7),mat);stem.position.set(x,.1,z);stem.castShadow=true;scene.add(stem);const leaf=new THREE.Mesh(new THREE.SphereGeometry(.18+Math.random()*.12,9,7),mat);leaf.scale.set(1,.4,2);leaf.position.set(x,.48,z);leaf.rotation.y=angle;scene.add(leaf);if(i%4===0){const ring=new THREE.Mesh(new THREE.TorusGeometry(.16,.025,8,24),goldMat);ring.position.set(x,.82,z);ring.rotation.x=Math.PI/2;scene.add(ring)}}}
function addEvents(){addEventListener('resize',onResize);addEventListener('keydown',e=>{const map={ArrowUp:{x:0,z:-1},w:{x:0,z:-1},ArrowDown:{x:0,z:1},s:{x:0,z:1},ArrowLeft:{x:-1,z:0},a:{x:-1,z:0},ArrowRight:{x:1,z:0},d:{x:1,z:0}};if(e.key===' '){e.preventDefault();togglePause();return}const dir=map[e.key]||map[e.key.toLowerCase()];if(dir){e.preventDefault();setDirection(dir)}});$('#startBtn').addEventListener('click',()=>{if(over)resetGame(true);running=true;paused=false;$('#overlay').classList.add('hidden');$('#pauseBtn').textContent='Ⅱ';});$('#pauseBtn').addEventListener('click',togglePause);$('#soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('#soundBtn').style.color=soundOn?'#e6bd67':'';if(soundOn)beep(440,.05)});document.querySelectorAll('.pad').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();const dirs={up:{x:0,z:-1},down:{x:0,z:1},left:{x:-1,z:0},right:{x:1,z:0}};setDirection(dirs[b.dataset.dir])})});let touchStart=null;renderer.domElement.addEventListener('pointerdown',e=>{touchStart={x:e.clientX,y:e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{if(!touchStart)return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;if(Math.abs(dx)>Math.abs(dy))setDirection({x:Math.sign(dx),z:0});else setDirection({x:0,z:Math.sign(dy)})});$('#overlay').addEventListener('pointerdown',e=>{if(e.target===$('#overlay'))e.preventDefault()});}
function onResize(){if(!renderer||!camera)return;const w=innerWidth,h=innerHeight,aspect=w/h;camera.aspect=aspect;camera.fov=aspect<.75?47:39;const zoom=aspect<.75?1.52:1;camera.position.set(0,19*zoom,23*zoom);camera.lookAt(0,0,0);camera.updateProjectionMatrix();renderer.setSize(w,h);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))}
function setDirection(dir){if(dir.x===-heading.x&&dir.z===-heading.z)return;queuedDir=dir;if(!running&&!over&&$('#overlay').classList.contains('hidden'))running=true}
function togglePause(){if(over)return;if(!running&&!paused)return;if(paused){paused=false;running=true;$('#overlay').classList.add('hidden');$('#pauseBtn').textContent='Ⅱ'}else{paused=true;running=false;$('#eyebrow').textContent='Take your time';$('#title').innerHTML='A moment<br>to breathe.';$('#message').textContent='Your fortune is right where you left it. Ready when you are.';$('#startBtn').textContent='Resume run';$('#overlay').classList.remove('hidden');$('#pauseBtn').textContent='▶'}}
function resetGame(startNow=true){for(const p of pickups)scene.remove(p);pickups=[];snake=START.map(p=>({...p}));heading={x:1,z:0};queuedDir={x:1,z:0};score=0;stepDuration=.19;stepTimer=0;over=false;paused=false;running=startNow;updateSnakeMesh();for(let i=0;i<4;i++)spawnCash();updateHud();if(startNow)$('#overlay').classList.add('hidden')}
function moveStep(){heading={...queuedDir};const head={x:snake[0].x+heading.x,z:snake[0].z+heading.z};const eaten=pickups.find(p=>p.userData.grid.x===head.x&&p.userData.grid.z===head.z);if(Math.abs(head.x)>GRID/2-1||Math.abs(head.z)>GRID/2-1||snake.slice(0,eaten?-0:-1).some((p,i)=>i>0&&p.x===head.x&&p.z===head.z)){endGame();return}snakeView.old=snake.map(p=>({...p}));snake.unshift(head);if(eaten){score+=25;score=Math.max(0,score);scene.remove(eaten);pickups=pickups.filter(p=>p!==eaten);snake.push({...snake[snake.length-1]});stepDuration=Math.max(.105,stepDuration*.985);updateSnakeMesh();spawnCash();showToast();beep(660,.1);burst(head.x,head.z)}else snake.pop();}
function endGame(){running=false;over=true;best=Math.max(best,score);localStorage.setItem('jadeBest',best);$('#eyebrow').textContent='Run complete · best $'+String(best).padStart(3,'0');$('#title').innerHTML='The vault<br>is yours.';$('#message').textContent=`You collected $${score} and grew to ${snake.length} segments. One more run?`;$('#startBtn').textContent='Run it back';$('#overlay').classList.remove('hidden');$('#pauseBtn').textContent='Ⅱ';beep(180,.18)}
function updateHud(){$('#score').textContent=String(score).padStart(3,'0');$('#length').textContent=String(snake.length).padStart(2,'0');$('#progress').style.width=`${Math.min(100,score/250*100)}%`}
let toastTimer;function showToast(){$('#toast').textContent='+$25 collected';$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),900);updateHud()}
function beep(freq,duration){if(!soundOn)return;try{audioCtx ||= new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function burst(x,z){const mat=new THREE.MeshBasicMaterial({color:0xf2d789,transparent:true,opacity:.9});for(let i=0;i<8;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.055,8,6),mat.clone());m.position.set(x,.5,z);m.userData.vel=v((Math.random()-.5)*.11,.04+Math.random()*.07,(Math.random()-.5)*.11);m.userData.life=.7;scene.add(m);particles.push(m)}}

