function burst(x,z){for(let i=0;i<8;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.055,8,6),new THREE.MeshBasicMaterial({color:0xf2d789,transparent:true,opacity:.9}));m.position.set(x,.5,z);m.userData.vel=v((Math.random()-.5)*.11,.04+Math.random()*.07,(Math.random()-.5)*.11);m.userData.life=.7;scene.add(m);particles.push(m)}}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05),elapsed=clock.elapsedTime;if(running&&!paused){stepTimer+=dt;while(stepTimer>=stepDuration&&running){stepTimer-=stepDuration;moveStep()}}if(snakeView){const t=running?Math.min(1,stepTimer/stepDuration):1;placeBody(t);snakeView.head.rotation.y=Math.atan2(heading.x,heading.z);snakeView.head.position.y=.35+Math.sin(elapsed*3)*.035;snakeView.head.userData.tongue.scale.z=.82+(Math.sin(elapsed*5)> .95?.38:0)}for(const p of pickups){p.position.y=.32+Math.sin(elapsed*2.2+p.userData.phase)*.08;p.rotation.y+=dt*.32;p.scale.setScalar((.78+Math.sin(elapsed*2+p.userData.phase)*.025))}for(const m of [...particles]){m.userData.life-=dt;m.position.addScaledVector(m.userData.vel,dt*9);m.userData.vel.y-=dt*.2;m.material.opacity=Math.max(0,m.userData.life/.7);if(m.userData.life<=0){scene.remove(m);particles.splice(particles.indexOf(m),1)}}renderer.render(scene,camera)}
